# Crea la carpeta de descarga de Hellspawn y su zip (para repartir gratis).
#  Resultado: D:\Proyectos\Hellspawn Diablo DSI\distribucion\Hellspawn_DSi\  y  ...\distribucion\Hellspawn_DSi.zip
#  Necesita (el script avisa si falta algo):
#   - ~/devilutionx_test.nds                       (el juego compilado)
#   - ~/devilutionX/build-nds/assets/              (assets de DevilutionX + imagenes de Hellspawn)
#   - herramientas\diablo\unpack_and_minify_mpq_x86_64.exe
#   - herramientas\ffmpeg.exe                          (version para Windows, ver LEEME)
#   - el compilador de Windows: sudo apt install -y gcc-mingw-w64-x86-64
import os, sys, shutil, subprocess, zipfile, base64

home = os.path.expanduser('~')
PROY = '/mnt/d/Proyectos/Hellspawn Diablo DSI'  # NDS-DISCOD: todo el proyecto en el disco D
DL = os.path.join(PROY, 'herramientas')
OUT = os.path.join(PROY, 'distribucion', 'Hellspawn_DSi')
SRC_C = base64.b64decode('').decode('utf-8')

NDS = os.path.join(home, 'devilutionx_test.nds')
ASSETS = os.path.join(home, 'devilutionX', 'build-nds', 'assets')
UNPACK = os.path.join(DL, 'diablo', 'unpack_and_minify_mpq_x86_64.exe')
FFMPEG = os.path.join(DL, 'ffmpeg.exe')
DX_LICENSE = os.path.join(home, 'devilutionX', 'LICENSE.md')
HF_MOD = os.path.join(home, 'devilutionX', 'mods', 'hf')  # NDS-HF: mod 'hf' de DevilutionX (necesario para Hellfire)

LEEME = r'''HELLSPAWN - Diablo DSI
Port de Diablo para Nintendo DSi, por Vanar
==========================================================

ESTE PORT ES GRATUITO. No se puede vender ni cobrar por el.
Si pagaste por esto, te han estafado.

No incluye ningun archivo de Blizzard: necesitas tu propio
DIABDAT.MPQ de una copia original de Diablo (por ejemplo, la
version de GOG). Lo encuentras en la carpeta de instalacion
del juego.

----------------------------------------------------------
COMO INSTALARLO (Windows)
----------------------------------------------------------
1. Descomprime este zip en tu PC (no lo ejecutes desde
   dentro del zip).
2. Mete la tarjeta SD de tu DSi en el PC.
3. Haz doble clic en "Instalar Hellspawn.exe".
4. Pulsa "Buscar..." y elige tu DIABDAT.MPQ (si tienes
   Hellfire, marca la casilla), elige la letra de la SD y
   como quieres los datos, y pulsa INSTALAR.
   (preparar_sd.exe hace lo mismo en una ventana de texto.)
5. No cierres la ventana: te avisa cuando termina.
6. Espera: desempaqueta los datos, copia lo necesario,
   convierte las cinematicas y copia hellspawn.nds a la SD.
   Tarda varios minutos. Hacen falta unos 1200 MB libres.
7. Pon la SD en la DSi y abre hellspawn.nds desde
   TWiLight Menu++ (en modo DSi).

En la SD queda:
   hellspawn.nds
   devilutionx\assets   devilutionx\diabdat
   devilutionx\dsv      devilutionx\saves (partidas)
   devilutionx\mods\hf  (lo usa Hellfire)

----------------------------------------------------------
TODO EN UN SOLO ARCHIVO .NDS (OPCIONAL)
----------------------------------------------------------
preparar_sd.exe pregunta como quieres los datos:
  1) sueltos en la SD (lo normal), o
  2) todo dentro de un solo archivo: hellspawn_completo.nds
Con la opcion 2, en la SD solo quedan hellspawn_completo.nds y
la carpeta devilutionx\saves (tus partidas siempre van en la
SD). Abre hellspawn_completo.nds desde TWiLight Menu++.
Mientras se prepara hace falta espacio libre en el PC (en la
carpeta de preparar_sd.exe), unos 1500 MB.
En melonDS el .nds tiene que estar dentro de la carpeta sd
(preparar_sd lo deja ahi).

----------------------------------------------------------
HELLFIRE (OPCIONAL)
----------------------------------------------------------
Si tienes la expansion Hellfire (viene con Diablo en GOG),
deja hellfire.mpq, hfmonk.mpq, hfmusic.mpq y hfvoice.mpq en la
misma carpeta que tu DIABDAT.MPQ (o junto a preparar_sd.exe).
preparar_sd.exe los encuentra y pregunta si quieres instalarlos;
si no, te deja arrastrar hellfire.mpq o seguir sin Hellfire.
Con Hellfire hacen falta unos 1450 MB libres.
Para cambiar entre Diablo y Hellfire: Opciones > Juego
(guarda la eleccion y hay que volver a abrir Hellspawn).

Si falta algo, el juego muestra una pantalla diciendo que.

----------------------------------------------------------
CREDITOS Y AGRADECIMIENTOS
----------------------------------------------------------
- Vanar: port a Nintendo DSi.
- Night Stroke: imagen del menu principal e icono
  (usadas con su permiso).
- Yagatsu18: betatester.
- DevilutionX (github.com/diasurgical/devilutionX): el codigo
  en el que se basa este port.
- Blizzard North: por crear Diablo.

----------------------------------------------------------
LICENCIAS
----------------------------------------------------------
Hellspawn es una VERSION MODIFICADA de DevilutionX, adaptada
a la Nintendo DSi. DevilutionX se distribuye bajo la licencia
"Sustainable Use License" (ver LICENCIAS\DevilutionX_LICENSE.md):
solo se permite repartirlo gratis y sin fines comerciales.

Diablo es una marca de Blizzard Entertainment. Este proyecto no
esta afiliado ni respaldado por Blizzard.

Herramientas incluidas (cada una con su licencia, ver LICENCIAS):
- unpack_and_minify_mpq (proyecto DevilutionX)
- FFmpeg (ffmpeg.org) para convertir las cinematicas
- preparar_sd.exe: su codigo fuente va en LICENCIAS\preparar_sd.c
- crear_nds.exe: su codigo fuente va en LICENCIAS\crear_nds.c
- Instalar Hellspawn.exe: su codigo fuente va en LICENCIAS\instalador.c
  (imagen de fondo: arte de Night Stroke)

JUGAR EN EL EMULADOR melonDS (PC)
---------------------------------
1. Haz doble clic en preparar_sd.exe y elige la opcion 2
   (carpeta para melonDS). Por defecto usa C:\melonDS.
2. En melonDS (version 1.1 o posterior), Config > Emu settings:
   - Consola en modo DSi (necesitas la BIOS, el firmware y la
     NAND de tu propia DSi).
   - Pestana DLDI: Enable DLDI; SD card image C:\melonDS\dldi_sd.bin
     (1 GB); Sync SD to folder C:\melonDS\sd
   - Pestana DSi-mode: SD card image C:\melonDS\dsi_vacia.bin;
     Sync SD to folder C:\melonDS\sd_vacia (debe quedar vacia)
3. Abre C:\melonDS\hellspawn.nds en melonDS.
Nota: en melonDS se usa DLDI porque escribir en la SD interna de
la DSi emulada se cuelga (las partidas no se podrian guardar).
El multijugador local no esta probado en melonDS.
'''

FFMPEG_NOTE = '''FFmpeg (https://ffmpeg.org) se incluye sin modificar como
herramientas\\ffmpeg.exe para convertir las cinematicas.
FFmpeg se distribuye bajo la licencia LGPL/GPL (segun la
compilacion). El codigo fuente esta disponible en
https://ffmpeg.org/download.html
'''

UNPACK_NOTE = '''unpack_and_minify_mpq forma parte de las herramientas MPQ del
proyecto DevilutionX (https://github.com/diasurgical/devilutionx-mpq-tools).
Se incluye sin modificar como herramientas\\unpack_and_minify_mpq.exe.
Consulta su licencia en el repositorio indicado.
'''


def need(path, what):
    if not os.path.exists(path):
        print('FALTA', what + ':', path)
        return False
    return True


ok = all([
    need(NDS, 'el juego compilado (ejecuta ~/devilutionX/nds/compilar.sh)'),
    need(ASSETS, 'la carpeta de assets'),
    need(UNPACK, 'el desempaquetador'),
    need(FFMPEG, 'ffmpeg.exe para Windows (mira el mensaje del asistente)'),
])
if not shutil.which('x86_64-w64-mingw32-gcc'):
    print('FALTA el compilador de Windows: sudo apt install -y gcc-mingw-w64-x86-64')
    ok = False
if not ok:
    sys.exit(1)
for f in ('hellspawn.clx', 'hellspawn.pal', 'hellspawn_arriba.bin'):
    if not os.path.exists(os.path.join(ASSETS, 'ui_art', f)):
        print('AVISO: falta assets/ui_art/' + f + ' (la pantalla de titulo o la de arriba saldran sin la imagen)')

if os.path.exists(OUT):
    shutil.rmtree(OUT)
os.makedirs(os.path.join(OUT, 'herramientas'))
os.makedirs(os.path.join(OUT, 'datos'))
os.makedirs(os.path.join(OUT, 'LICENCIAS'))

# preparar_sd.exe
build = os.path.join(home, 'hellspawn_dist')
os.makedirs(build, exist_ok=True)
c_path = os.path.join(build, 'preparar_sd.c')
open(c_path, 'w').write(SRC_C)
exe = os.path.join(build, 'preparar_sd.exe')
r = subprocess.run(['x86_64-w64-mingw32-gcc', '-O2', '-s', '-static', '-o', exe, c_path])
if r.returncode != 0:
    print('ERROR al compilar preparar_sd.exe (pegale la salida al asistente)')
    sys.exit(1)
shutil.copy(exe, os.path.join(OUT, 'preparar_sd.exe'))
shutil.copy(c_path, os.path.join(OUT, 'LICENCIAS', 'preparar_sd.c'))
print('preparar_sd.exe compilado')
# NDS-TODO: crear_nds.exe (mete los datos dentro del .nds)
CREAR_C = os.path.join(PROY, 'scripts', 'crear_nds', 'crear_nds.c')
cexe = os.path.join(build, 'crear_nds.exe')
r = subprocess.run(['x86_64-w64-mingw32-gcc', '-O2', '-s', '-static', '-o', cexe, CREAR_C])
if r.returncode != 0:
    print('ERROR al compilar crear_nds.exe (pegale la salida al asistente)')
    sys.exit(1)
shutil.copy(cexe, os.path.join(OUT, 'herramientas', 'crear_nds.exe'))
shutil.copy(CREAR_C, os.path.join(OUT, 'LICENCIAS', 'crear_nds.c'))
print('crear_nds.exe compilado')
# NDS-INSTALADOR: instalador con ventana
INST_C = os.path.join(PROY, 'scripts', 'instalador', 'instalador.c')
INST_BMP = os.path.join(PROY, 'scripts', 'instalador', 'fondo.bmp')
iexe = os.path.join(build, 'Instalar Hellspawn.exe')
r = subprocess.run(['x86_64-w64-mingw32-gcc', '-O2', '-s', '-static', '-municode', '-mwindows', '-o', iexe, INST_C,
                    '-lcomctl32', '-lcomdlg32', '-lshell32', '-lole32'])
if r.returncode != 0:
    print('ERROR al compilar el instalador con ventana (pegale la salida al asistente)')
    sys.exit(1)
shutil.copy(iexe, os.path.join(OUT, 'Instalar Hellspawn.exe'))
shutil.copy(INST_BMP, os.path.join(OUT, 'herramientas', 'fondo.bmp'))
shutil.copy(INST_C, os.path.join(OUT, 'LICENCIAS', 'instalador.c'))
print('Instalar Hellspawn.exe compilado')

shutil.copy(NDS, os.path.join(OUT, 'hellspawn.nds'))
shutil.copy(UNPACK, os.path.join(OUT, 'herramientas', 'unpack_and_minify_mpq.exe'))
shutil.copy(FFMPEG, os.path.join(OUT, 'herramientas', 'ffmpeg.exe'))
shutil.copytree(ASSETS, os.path.join(OUT, 'datos', 'devilutionx', 'assets'))
if os.path.isdir(HF_MOD):  # NDS-HF
    shutil.copytree(HF_MOD, os.path.join(OUT, 'datos', 'devilutionx', 'mods', 'hf'))
else:
    print('AVISO: no encontre ~/devilutionX/mods/hf: Hellfire no funcionara con este zip')
open(os.path.join(OUT, 'LEEME.txt'), 'w', newline='\r\n').write(LEEME)
open(os.path.join(OUT, 'LICENCIAS', 'FFmpeg.txt'), 'w', newline='\r\n').write(FFMPEG_NOTE)
open(os.path.join(OUT, 'LICENCIAS', 'unpack_and_minify_mpq.txt'), 'w', newline='\r\n').write(UNPACK_NOTE)
if os.path.exists(DX_LICENSE):
    shutil.copy(DX_LICENSE, os.path.join(OUT, 'LICENCIAS', 'DevilutionX_LICENSE.md'))
else:
    print('AVISO: no encontre ~/devilutionX/LICENSE.md; descargalo de github.com/diasurgical/devilutionX y ponlo en LICENCIAS')

zpath = OUT + '.zip'
if os.path.exists(zpath):
    os.remove(zpath)
with zipfile.ZipFile(zpath, 'w', zipfile.ZIP_DEFLATED) as z:
    for root, _, files in os.walk(OUT):
        for f in files:
            full = os.path.join(root, f)
            z.write(full, os.path.join('Hellspawn_DSi', os.path.relpath(full, OUT)))
print('listo:')
print('  carpeta:', OUT)
print('  zip:    ', zpath, '(%.1f MB)' % (os.path.getsize(zpath) / 1048576))
